-- ============================================================
--  Тема «Минулі часи (Past Tenses)»: теорія у кроковому форматі + вправи
--  Згенеровано з mig/past_tenses.js — вручну не редагувати.
--  Потребує 06_theory_structure.sql. Повторний запуск безпечний.
-- ============================================================
begin;

alter table public.topics        add column if not exists subtopics jsonb not null default '[]'::jsonb;
alter table public.theory_blocks add column if not exists subtopic  text;
alter table public.exercises     add column if not exists subtopic  text;

create unique index if not exists uq_exercises_legacy_shared
  on public.exercises (legacy_id) where student_id is null;
-- тип вправи «translate» (переклад і письмо) дозволено в exercises.type
alter table public.exercises drop constraint if exists exercises_type_check;
alter table public.exercises add constraint exercises_type_check
  check (type in ('order', 'choice', 'gap', 'cross', 'abcd', 'translate'));
alter table public.theory_blocks drop constraint if exists theory_blocks_kind_check;
alter table public.theory_blocks add constraint theory_blocks_kind_check
  check (kind in ('prose', 'hero', 'cases', 'formula', 'traps', 'pairs'));

insert into public.topics (slug, title, description, position, subtopics)
values ($g0$past_tenses$g0$, $g1$Минулі часи (Past Tenses)$g1$, $g2$Past Simple, Past Continuous, Past Perfect і Past Perfect Continuous: форми, вживання, слова-маркери, типові помилки, порівняння часів. Є вправи на переклад речень з перевіркою й поясненням помилок.$g2$, 14, $g3$[{"slug":"past_simple","title":"Past Simple: завершена дія в минулому","description":"Дія, що відбулась і закінчилась у минулому: точний час, послідовність дій, минулі звички. Правильні й неправильні дієслова."},{"slug":"past_cont","title":"Past Continuous: дія в процесі в минулому","description":"Дія тривала в певний момент або період у минулому, фон для іншої дії, одночасні дії. While, when, as."},{"slug":"past_perf","title":"Past Perfect: раніше за іншу дію в минулому","description":"Дія завершилась до певного моменту або до іншої минулої дії. After, before, by, already, just."},{"slug":"past_perf_cont","title":"Past Perfect Continuous: тривала дія до моменту в минулому","description":"Дія тривала певний час до іншого моменту в минулому; причина стану в минулому. For, since, all day, how long."},{"slug":"past_mix","title":"Усі минулі часи разом","description":"Порівняння чотирьох часів, вибір потрібного, змішані вправи й тести. Окремої теорії тут мало: усе — у попередніх підтемах.","mix":true}]$g3$::jsonb)
on conflict (slug) do update set title = excluded.title,
  description = excluded.description, position = excluded.position, subtopics = excluded.subtopics;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g4$pas_form$g4$, $g5$Past Simple: як утворюється$g5$, $g6$elementary$g6$, $g7$formula$g7$, $g8${"step":"Past Simple: як утворюється","kicker":"Як утворюється","lead":"Past Simple — найпростіший минулий час. У ствердженні це <b>друга форма дієслова (V2)</b>: правильні дієслова мають закінчення <b>-ed</b>, неправильні треба вчити (<i>go – went</i>). У запереченні й питанні з'являється допоміжне <b>did</b>, і дієслово знову стає початковою формою.","tiles":[{"role":"підмет","label":"I / he / they…","tone":"noun"},{"role":"V2","label":"worked / went","tone":"colour"}],"legend":[{"tone":"noun","label":"підмет не впливає на форму: I worked, he worked, they worked"},{"tone":"colour","label":"заперечення й питання: did + дієслово без закінчення"}],"examples":[{"text":"We <b>visited</b> our friends last Sunday.","plain":"We visited our friends last Sunday.","note":"ствердження"},{"text":"She <b>went</b> to Rome in May.","plain":"She went to Rome in May.","note":"неправильне дієслово"},{"text":"I <b>didn't see</b> him yesterday.","plain":"I didn't see him yesterday.","note":"заперечення"},{"text":"<b>Did</b> you <b>call</b> her? — Yes, I <b>did</b>.","plain":"Did you call her? Yes, I did.","note":"питання й коротка відповідь"},{"text":"<b>Was</b> he at home? — No, he <b>wasn't</b>.","plain":"Was he at home? No, he wasn't.","note":"to be: was / were"}],"note":"<b>To be</b> має форми <b>was</b> (I, he, she, it) і <b>were</b> (you, we, they) і допоміжного did не потребує: <i>Were you ready? She wasn't at home.</i>","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Ствердження</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Заперечення</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Питання</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">I / you / he / she / it / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">worked / went</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">didn't (did not) work</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Did he work?</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">to be: I / he / she / it</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">was</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">wasn't</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Was he…?</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">to be: you / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">were</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">weren't</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Were you…?</td></tr></tbody>\n</table></div>"}]}$g8$::jsonb, null, 0, $g9$past_simple$g9$
from public.topics where slug = $g10$past_tenses$g10$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g11$pas_use$g11$, $g12$Past Simple: коли вживаємо$g12$, $g13$elementary$g13$, $g14$cases$g14$, $g15${"kicker":"Коли вживаємо","lead":"Past Simple розповідає про минуле як про «закриту сторінку»: дія відбулась і закінчилась, а з теперішнім її нічого не пов'язує.","cards":[{"icon":"✓","title":"Завершена дія в минулому","text":"Дія відбулась у певний час, який уже скінчився. Час часто названо (yesterday, in 2019, ago).","example":"She <b>came</b> home <b>at 5 o'clock yesterday</b>.","examplePlain":"She came home at 5 o'clock yesterday."},{"icon":"→","title":"Послідовність дій","text":"Одна дія за іншою: ми розповідаємо історію в хронологічному порядку.","example":"He <b>opened</b> the door, <b>went</b> in and <b>sat down</b>.","examplePlain":"He opened the door, went in and sat down."},{"icon":"↻","title":"Минулі звички й повторювані дії","text":"Те, що траплялось регулярно, але вже не так (часто з used to).","example":"When I was a child, I <b>played</b> in the yard every day.","examplePlain":"When I was a child, I played in the yard every day."},{"icon":"∞","title":"Стан у минулому","text":"Тривалий стан, що закінчився: жив, працював, був.","example":"She <b>lived</b> in London for ten years (а тепер там не живе).","examplePlain":"She lived in London for ten years (а тепер там не живе)."}]}$g15$::jsonb, null, 1, $g16$past_simple$g16$
from public.topics where slug = $g17$past_tenses$g17$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g18$pas_markers$g18$, $g19$Past Simple: маркери й правопис$g19$, $g20$elementary$g20$, $g21$pairs$g21$, $g22${"step":"Past Simple: маркери й правопис","kicker":"Слова-маркери","lead":"Точні минулі маркери завжди вказують на Past Simple: дія закінчилась у чітко названий проміжок, який уже минув.","groups":[{"title":"Маркери часу","note":"точний минулий час","items":[["yesterday","I saw him yesterday."],["last week / month / year","We moved last year."],["two days ago","She called two days ago."],["in 2019 / in May","He graduated in 2019."],["when …? (минуле)","When did you arrive?"],["the other day","I met her the other day."]]},{"title":"Закінчення -ed","note":"правопис правильних дієслів","items":[["work → worked","просто + ed"],["like → liked","-e: додаємо тільки -d"],["study → studied","приголосна + y → ied"],["play → played","голосна + y → yed"],["stop → stopped","одна голосна + одна приголосна: подвоюємо"]]},{"title":"Вимова -ed","note":"три варіанти","items":[["worked, stopped","після глухих: [t]"],["played, called","після дзвінких і голосних: [d]"],["wanted, needed","після t і d: [ɪd]"]]}],"notes":["<b>Неправильні дієслова</b> (go – went, see – saw, buy – bought) вчимо з таблиці. У запереченні й питанні вони стають початковою формою: <i>He went → He didn't go. Did he go?</i>"]}$g22$::jsonb, null, 2, $g23$past_simple$g23$
from public.topics where slug = $g24$past_tenses$g24$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position, subtopic = excluded.subtopic;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g25$pas_traps$g25$, $g26$Past Simple: типові помилки$g26$, $g27$intermediate$g27$, $g28$traps$g28$, $g29${"kicker":"Типові помилки","lead":"Найчастіше плутають V2 після did, забувають did у запереченні та вживають Present Perfect з точним минулим часом.","items":[{"title":"Друга форма після did","bad":"Did you saw him? She didn't went there.","good":"Did you <b>see</b> him? She didn't <b>go</b> there.","goodPlain":"Did you see him? She didn't go there.","rule":"Минулий час уже виражає did, тому основне дієслово — початкова форма."},{"title":"Заперечення без did","bad":"I not saw him. He no came.","good":"I <b>didn't see</b> him. He <b>didn't come</b>.","goodPlain":"I didn't see him. He didn't come.","rule":"Заперечення у Past Simple створює did + not."},{"title":"Present Perfect із точним часом","bad":"I have seen him yesterday.","good":"I <b>saw</b> him yesterday.","goodPlain":"I saw him yesterday.","rule":"Yesterday, ago, last week, in 2019 — тільки Past Simple."},{"title":"Did у запереченні разом із V2","bad":"He didn't came yesterday.","good":"He didn't <b>come</b> yesterday.","goodPlain":"He didn't come yesterday.","rule":"Один показник минулого: або did, або V2."},{"title":"Was / were з did","bad":"Did you were at home? He didn't was there.","good":"<b>Were</b> you at home? He <b>wasn't</b> there.","goodPlain":"Were you at home? He wasn't there.","rule":"To be не потребує did: питання — переставляємо, заперечення — wasn't / weren't."}]}$g29$::jsonb, null, 3, $g30$past_simple$g30$
