insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g32$pac_form$g32$, $g33$Past Continuous: як утворюється$g33$, $g34$elementary$g34$, $g35$formula$g35$, $g36${"step":"Past Continuous: як утворюється","kicker":"Як утворюється","lead":"Past Continuous = <b>was / were</b> + дієслово з <b>-ing</b>. Допоміжне змінюється за підметом: <b>was</b> для I, he, she, it; <b>were</b> для you, we, they.","tiles":[{"role":"підмет","label":"I / he / we…","tone":"noun"},{"role":"was / were","label":"was","tone":"colour"},{"role":"V-ing","label":"working","tone":"origin"}],"legend":[{"tone":"noun","label":"I / he / she / it → was; you / we / they → were"},{"tone":"origin","label":"правопис -ing такий самий, як у Present Continuous"}],"examples":[{"text":"He <b>was working</b> at 5 o'clock yesterday.","plain":"He was working at 5 o'clock yesterday.","note":"ствердження"},{"text":"They <b>weren't sleeping</b> at midnight.","plain":"They weren't sleeping at midnight.","note":"заперечення"},{"text":"<b>Were</b> you <b>reading</b> when I called?","plain":"Were you reading when I called?","note":"питання"},{"text":"What <b>was</b> she <b>doing</b> at that time?","plain":"What was she doing at that time?","note":"спеціальне питання"}],"note":"Скорочення: <i>wasn't, weren't</i>. У питанні was / were виходить на перше місце: <i>Was he sleeping?</i>","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Ствердження</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Заперечення</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Питання</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">I / he / she / it</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">was working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">wasn't working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Was he working?</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">you / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">were working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">weren't working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Were you working?</td></tr></tbody>\n</table></div>"}]}$g36$::jsonb, null, 4, $g37$past_cont$g37$
