insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g39$pac_use$g39$, $g40$Past Continuous: коли вживаємо$g40$, $g41$elementary$g41$, $g42$cases$g42$, $g43${"kicker":"Коли вживаємо","lead":"Past Continuous показує дію «в процесі» в минулому: вона почалась раніше й ще тривала в потрібний момент.","cards":[{"icon":"●","title":"Дія в певний момент у минулому","text":"Що відбувалось саме тоді, коли названо точний час.","example":"At 8 o'clock yesterday I <b>was having</b> breakfast.","examplePlain":"At 8 o'clock yesterday I was having breakfast."},{"icon":"⌛","title":"Дія тривала протягом періоду","text":"Весь день, цілий вечір, з п'яти до сьомої.","example":"They <b>were playing</b> chess <b>from 5 to 7</b>.","examplePlain":"They were playing chess from 5 to 7."},{"icon":"⚡","title":"Фон і перервана дія","text":"Тривала дія (Past Continuous) і коротка подія, що її перервала (Past Simple).","example":"I <b>was walking</b> home when it <b>started</b> to rain.","examplePlain":"I was walking home when it started to rain."},{"icon":"⇄","title":"Дві одночасні дії","text":"Обидві тривали разом (while, as).","example":"Tom <b>was reading</b> while Ann <b>was cooking</b>.","examplePlain":"Tom was reading while Ann was cooking."},{"icon":"😠","title":"Роздратування з always","text":"Постійні повторення, що дратували.","example":"He <b>was always complaining</b> about something.","examplePlain":"He was always complaining about something."}],"axis":{"title":"Past Continuous і Past Simple на осі","points":[{"label":"раніше","text":"Past Continuous: дія почалась і тривала"},{"label":"момент","text":"Past Simple: коротка подія її перервала"},{"label":"після","text":"дія могла продовжитись"}],"note":"Довга дія — Past Continuous, коротка подія, що її перервала, — Past Simple."}}$g43$::jsonb, null, 5, $g44$past_cont$g44$
