insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g46$pac_markers$g46$, $g47$Past Continuous: маркери й сполучники$g47$, $g48$elementary$g48$, $g49$pairs$g49$, $g50${"step":"Past Continuous: маркери й сполучники","kicker":"Слова-маркери","lead":"Маркери показують момент або період, у який дія тривала, а сполучники — як дії співвідносяться.","groups":[{"title":"Момент або період","note":"що саме відбувалось","items":[["at 5 o'clock yesterday","I was working at 5 o'clock yesterday."],["at that moment","She was sleeping at that moment."],["from 3 to 5","They were swimming from 3 to 5."],["all day / all evening","He was studying all evening."],["the whole morning","We were cleaning the whole morning."]]},{"title":"Сполучники","note":"як з'єднуємо дії","items":[["while + Past Continuous","While I was cooking, he was watching TV."],["when + Past Simple","I was cooking when he came."],["as","As I was walking, I met a friend."],["when + Past Continuous","When I was walking, it started to rain."]]}],"notes":["<b>While</b> зазвичай стоїть перед тривалою дією (Past Continuous), <b>when</b> — перед короткою подією (Past Simple): <i>While I was sleeping, the phone rang. I was sleeping when the phone rang.</i>"]}$g50$::jsonb, null, 6, $g51$past_cont$g51$
