insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g53$pac_vs_ps$g53$, $g54$Past Continuous чи Past Simple?$g54$, $g55$elementary$g55$, $g56$pairs$g56$, $g57${"step":"Past Continuous чи Past Simple?","kicker":"Порівняння","lead":"Past Simple називає факт, що дія відбулась і завершена. Past Continuous показує процес: що відбувалось у певний момент.","groups":[{"title":"Past Simple","note":"факт, завершена дія","items":[["дія завершилась повністю","I read a book yesterday. (прочитав)"],["послідовні дії","He opened the door and went in."],["коротка подія","The phone rang."],["дієслова стану","I knew the answer. She liked the film."]]},{"title":"Past Continuous","note":"процес, фон","items":[["дія тривала й могла не закінчитись","I was reading a book at 8 yesterday."],["одночасні дії","She was cooking while he was reading."],["тривалий фон","It was raining when we left."],["перервана дія","I was crossing the road when I fell."]]}],"notes":["<b>Порівняйте:</b> <i>When Tom came, we had dinner</i> (спершу він прийшов, потім сіли обідати) — <i>When Tom came, we were having dinner</i> (ми вже обідали, коли він прийшов)."]}$g57$::jsonb, null, 7, $g58$past_cont$g58$
