insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g60$pac_traps$g60$, $g61$Past Continuous: типові помилки$g61$, $g62$intermediate$g62$, $g63$traps$g63$, $g64${"kicker":"Типові помилки","lead":"Помилки бувають у структурі (was / were + -ing), у виборі між Simple та Continuous і в дієсловах стану.","items":[{"title":"Забули was / were","bad":"She watching TV at 8 o'clock.","good":"She <b>was watching</b> TV at 8 o'clock.","goodPlain":"She was watching TV at 8 o'clock.","rule":"Past Continuous = was / were + -ing."},{"title":"was / were переплутали","bad":"We was playing. He were sleeping.","good":"We <b>were</b> playing. He <b>was</b> sleeping.","goodPlain":"We were playing. He was sleeping.","rule":"I / he / she / it → was; you / we / they → were."},{"title":"Дієслово стану в Continuous","bad":"I was knowing the answer. She was wanting tea.","good":"I <b>knew</b> the answer. She <b>wanted</b> tea.","goodPlain":"I knew the answer. She wanted tea.","rule":"Know, want, like, understand — стан: Past Simple."},{"title":"Past Simple замість Continuous для процесу","bad":"At 8 o'clock I watched TV.","good":"At 8 o'clock I <b>was watching</b> TV.","goodPlain":"At 8 o'clock I was watching TV.","rule":"Дія в певний момент у процесі: Past Continuous."},{"title":"Continuous для короткої події","bad":"I was falling when I was crossing the road.","good":"I <b>fell</b> when I <b>was crossing</b> the road.","goodPlain":"I fell when I was crossing the road.","rule":"Коротка подія, що перервала дію, — Past Simple."}]}$g64$::jsonb, null, 8, $g65$past_cont$g65$
