insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g67$paf_form$g67$, $g68$Past Perfect: як утворюється$g68$, $g69$elementary$g69$, $g70$formula$g70$, $g71${"step":"Past Perfect: як утворюється","kicker":"Як утворюється","lead":"Past Perfect = <b>had</b> + <b>третя форма</b> дієслова (V3). <b>Had</b> однакове для всіх осіб: I had, he had, they had. Правильні дієслова: V + ed; неправильні вчимо (<i>go – went – gone</i>).","tiles":[{"role":"підмет","label":"I / he / they…","tone":"noun"},{"role":"had","label":"had","tone":"colour"},{"role":"V3","label":"finished / gone","tone":"origin"}],"legend":[{"tone":"noun","label":"для всіх осіб — had"},{"tone":"origin","label":"правильні: V + ed; неправильні: третя колонка таблиці"}],"examples":[{"text":"She <b>had finished</b> work by 5 o'clock.","plain":"She had finished work by 5 o'clock.","note":"ствердження"},{"text":"They <b>hadn't left</b> when we arrived.","plain":"They hadn't left when we arrived.","note":"заперечення"},{"text":"<b>Had</b> you <b>seen</b> him before?","plain":"Had you seen him before?","note":"питання"},{"text":"What <b>had</b> he <b>done</b> before you came?","plain":"What had he done before you came?","note":"спеціальне питання"}],"note":"Скорочення: <i>I'd, he'd, they'd, hadn't</i>. Але <i>he'd</i> може бути й <i>he would</i>, тому дивіться, що стоїть далі: <i>he'd gone</i> = had gone.","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Ствердження</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Заперечення</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Питання</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">I / you / he / she / it / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">had worked</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">hadn't worked</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Had he worked?</td></tr></tbody>\n</table></div>"}]}$g71$::jsonb, null, 9, $g72$past_perf$g72$
