insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g74$paf_use$g74$, $g75$Past Perfect: коли вживаємо$g75$, $g76$elementary$g76$, $g77$cases$g77$, $g78${"kicker":"Коли вживаємо","lead":"Past Perfect — це «минуле в минулому»: дія, що відбулась раніше за іншу минулу дію або до певного моменту в минулому.","cards":[{"icon":"⇤","title":"Раніше за іншу минулу дію","text":"Дві минулі дії: раніша — Past Perfect, пізніша — Past Simple.","example":"When I <b>came</b>, they <b>had</b> already <b>left</b>.","examplePlain":"When I came, they had already left."},{"icon":"⏱","title":"До певного моменту в минулому","text":"З маркерами by, by the time, by 5 o'clock yesterday.","example":"She <b>had finished</b> the report <b>by 5 o'clock</b>.","examplePlain":"She had finished the report by 5 o'clock."},{"icon":"?","title":"Причина, що пояснює минулу ситуацію","text":"Чому щось було саме так: бо раніше сталось інше.","example":"He was upset because he <b>had lost</b> his keys.","examplePlain":"He was upset because he had lost his keys."},{"icon":"💬","title":"Непряма мова в минулому","text":"Переказ того, що вже відбулось раніше.","example":"She said she <b>had seen</b> him.","examplePlain":"She said she had seen him."}],"axis":{"title":"Past Perfect на осі","points":[{"label":"раніше","text":"had + V3: перша дія"},{"label":"потім","text":"Past Simple: друга дія"},{"label":"тепер","text":"розповідаємо про це"}],"note":"Раніша дія — Past Perfect, пізніша — Past Simple. Якщо дії йдуть підряд за порядком оповіді, Past Perfect не потрібен."}}$g78$::jsonb, null, 10, $g79$past_perf$g79$
