insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g81$paf_markers$g81$, $g82$Past Perfect: слова-маркери$g82$, $g83$elementary$g83$, $g84$pairs$g84$, $g85${"step":"Past Perfect: слова-маркери","kicker":"Слова-маркери","lead":"Маркери показують, що дія відбулась раніше іншого моменту в минулому.","groups":[{"title":"Сполучники","note":"з'єднують дві минулі дії","items":[["after + Past Perfect","After he had eaten, he went out."],["before + Past Simple","He had eaten before he went out."],["when","When I arrived, they had left."],["as soon as / by the time","By the time we arrived, the film had started."]]},{"title":"Слова часу","note":"місце в реченні","items":[["already","She had already left. (перед V3)"],["just","I had just come home. (перед V3)"],["yet / ever / never","He hadn't finished yet. Had you ever seen it?"],["by 5 o'clock / by the end of","They had finished by 5 o'clock."],["before / the day before","He had seen it the day before."]]}],"notes":["<b>After / before:</b> після <i>after</i> зазвичай ставимо Past Perfect, після <i>before</i> — Past Simple. Обидві конструкції описують те саме: <i>After I had eaten, I left = I had eaten before I left.</i>"]}$g85$::jsonb, null, 11, $g86$past_perf$g86$
