insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g88$paf_vs_ps$g88$, $g89$Past Perfect чи Past Simple?$g89$, $g90$elementary$g90$, $g91$pairs$g91$, $g92${"step":"Past Perfect чи Past Simple?","kicker":"Порівняння","lead":"Past Simple розповідає про дії в тому порядку, в якому вони відбувались. Past Perfect потрібен, коли ми «повертаємось назад» до того, що сталось раніше.","groups":[{"title":"Past Simple","note":"послідовність","items":[["дії одна за одною","She came, took her bag and left."],["не важливо, що було раніше","She left. I called her."]]},{"title":"Past Perfect","note":"раніше","items":[["одна дія раніше за іншу","When I called, she had left."],["до моменту в минулому","By 8 o'clock she had left."],["причина минулої ситуації","She was tired because she had worked all day."]]}],"notes":["<b>Порівняйте:</b> <i>When I came, he left</i> (він пішов після мого приходу) — <i>When I came, he had left</i> (він пішов до мого приходу)."]}$g92$::jsonb, null, 12, $g93$past_perf$g93$
