insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g95$paf_traps$g95$, $g96$Past Perfect: типові помилки$g96$, $g97$intermediate$g97$, $g98$traps$g98$, $g99${"kicker":"Типові помилки","lead":"Past Perfect вживають не там, де треба, або навпаки забувають, коли дія була раніше.","items":[{"title":"Past Simple замість Past Perfect","bad":"When I came, the film already started.","good":"When I came, the film <b>had</b> already <b>started</b>.","goodPlain":"When I came, the film had already started.","rule":"Раніша дія до іншого минулого моменту — Past Perfect."},{"title":"Past Perfect для послідовних дій","bad":"He had opened the door and had gone in.","good":"He <b>opened</b> the door and <b>went</b> in.","goodPlain":"He opened the door and went in.","rule":"Дії по черзі в порядку оповіді — Past Simple."},{"title":"Друга форма замість третьої","bad":"She had went home. They had saw it.","good":"She had <b>gone</b> home. They had <b>seen</b> it.","goodPlain":"She had gone home. They had seen it.","rule":"Після had — третя форма: go – went – gone."},{"title":"Past Perfect з точним часом без іншої дії","bad":"I had written my test at 2 o'clock.","good":"I <b>wrote</b> my test at 2 o'clock.","goodPlain":"I wrote my test at 2 o'clock.","rule":"Точний момент без by: Past Simple. By 2 o'clock → had written."},{"title":"Порядок слів у питанні","bad":"Why Sam hadn't called? Where Jane had gone?","good":"Why <b>hadn't Sam</b> called? Where <b>had Jane</b> gone?","goodPlain":"Why hadn't Sam called? Where had Jane gone?","rule":"Had виходить перед підметом."}]}$g99$::jsonb, null, 13, $g100$past_perf$g100$
