insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g102$pafc_form$g102$, $g103$Past Perfect Continuous: як утворюється$g103$, $g104$elementary$g104$, $g105$formula$g105$, $g106${"step":"Past Perfect Continuous: як утворюється","kicker":"Як утворюється","lead":"Past Perfect Continuous = <b>had been</b> + дієслово з <b>-ing</b>. Це Past Perfect (had + been) і Continuous (-ing) разом. Had однакове для всіх осіб.","tiles":[{"role":"підмет","label":"I / he / they…","tone":"noun"},{"role":"had been","label":"had been","tone":"colour"},{"role":"V-ing","label":"working","tone":"origin"}],"legend":[{"tone":"noun","label":"для всіх осіб — had been"},{"tone":"origin","label":"правопис -ing такий самий, як у Present Continuous"}],"examples":[{"text":"She <b>had been cooking</b> for two hours before we came.","plain":"She had been cooking for two hours before we came.","note":"ствердження"},{"text":"They <b>hadn't been waiting</b> long.","plain":"They hadn't been waiting long.","note":"заперечення"},{"text":"How long <b>had</b> you <b>been working</b> there?","plain":"How long had you been working there?","note":"питання"},{"text":"Why <b>had</b> he <b>been shouting</b>?","plain":"Why had he been shouting?","note":"спеціальне питання"}],"note":"Скорочення: <i>I'd been working, he'd been working, hadn't been</i>.","tabs":[{"title":"Усі форми","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Ствердження</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Заперечення</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">Питання</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">I / you / he / she / it / we / they</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">had been working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">hadn't been working</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">Had he been working?</td></tr></tbody>\n</table></div>"}]}$g106$::jsonb, null, 14, $g107$past_perf_cont$g107$
