insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g109$pafc_use$g109$, $g110$Past Perfect Continuous: коли вживаємо$g110$, $g111$elementary$g111$, $g112$cases$g112$, $g113${"kicker":"Коли вживаємо","lead":"Цей час відповідає на запитання «скільки це вже тривало до того моменту?» і «чому так було?».","cards":[{"icon":"→","title":"Тривала дія до моменту в минулому","text":"Дія почалась раніше й тривала певний час до моменту чи іншої минулої дії.","example":"They <b>had been waiting</b> for an hour when the bus arrived.","examplePlain":"They had been waiting for an hour when the bus arrived."},{"icon":"💪","title":"Причина стану в минулому","text":"Видимий результат довгої дії: чому щось було таким.","example":"His eyes were red because he <b>had been working</b> all night.","examplePlain":"His eyes were red because he had been working all night."},{"icon":"⏳","title":"Підкреслюємо тривалість","text":"Важливо, як довго: for, since, all day, how long.","example":"She <b>had been studying</b> all day.","examplePlain":"She had been studying all day."}],"axis":{"title":"Past Perfect Continuous на осі","points":[{"label":"початок","text":"дія почалась"},{"label":"тривала","text":"had been + V-ing: for / since"},{"label":"момент у минулому","text":"інша дія чи момент"}],"note":"Якщо другої минулої дії або моменту немає, то це зазвичай Past Continuous."}}$g113$::jsonb, null, 15, $g114$past_perf_cont$g114$
