insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g116$pafc_markers$g116$, $g117$Past Perfect Continuous: маркери$g117$, $g118$elementary$g118$, $g119$pairs$g119$, $g120${"step":"Past Perfect Continuous: маркери","kicker":"Слова-маркери","lead":"З цим часом майже завжди називається тривалість або момент початку, а також інша минула дія.","groups":[{"title":"Тривалість і початок","note":"типові слова","items":[["for two hours / a week","I had been waiting for two hours."],["since 5 o'clock / Monday","He had been working since morning."],["all day / all morning","She had been cooking all day."],["how long","How long had you been waiting?"],["before + Past Simple","He had been reading for an hour before he fell asleep."]]}],"notes":["<b>Дієслова стану</b> (know, like, want) не вживаються в Continuous, тому: <i>He had known her for years</i>, а не had been knowing."]}$g120$::jsonb, null, 16, $g121$past_perf_cont$g121$
