insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g123$pafc_vs_paf$g123$, $g124$Past Perfect чи Past Perfect Continuous?$g124$, $g125$elementary$g125$, $g126$pairs$g126$, $g127${"step":"Past Perfect чи Past Perfect Continuous?","kicker":"Порівняння","lead":"Обидва часи говорять про дію раніше за момент у минулому. Continuous дивиться на <b>процес і тривалість</b>, Perfect — на <b>результат і кількість</b>.","groups":[{"title":"Perfect Continuous: процес","note":"скільки тривало","items":[["How long?","She had been reading for two hours."],["видимий результат довгої дії","He was tired: he had been running."],["немає кількості","They had been playing all day."]]},{"title":"Past Perfect: результат","note":"скільки зроблено","items":[["How many? / how much?","She had read three chapters."],["дія завершена","He had painted the house. (готово)"],["дієслова стану","They had known each other for years."]]}],"notes":["<b>Порівняйте:</b> <i>She had been writing letters all morning</i> (процес) — <i>She had written ten letters</i> (кількість, результат)."]}$g127$::jsonb, null, 17, $g128$past_perf_cont$g128$
