insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g130$pafc_traps$g130$, $g131$Past Perfect Continuous: типові помилки$g131$, $g132$intermediate$g132$, $g133$traps$g133$, $g134${"kicker":"Типові помилки","lead":"Тут помиляються на три речі: структура (had been + -ing), Past Continuous без тривалості та дієслова стану.","items":[{"title":"Забули been","bad":"Rob and Jack had swimming for an hour.","good":"Rob and Jack <b>had been swimming</b> for an hour.","goodPlain":"Rob and Jack had been swimming for an hour.","rule":"had + been + V-ing: been обов'язкове."},{"title":"Past Continuous замість Past Perfect Continuous","bad":"She was waiting for two hours before he came.","good":"She <b>had been waiting</b> for two hours before he came.","goodPlain":"She had been waiting for two hours before he came.","rule":"Тривалість до іншої дії — Past Perfect Continuous."},{"title":"Дієслово стану","bad":"I had been knowing him for years.","good":"I <b>had known</b> him for years.","goodPlain":"I had known him for years.","rule":"Know, like, want, be (стан) — Past Perfect Simple."},{"title":"Порядок слів у питанні","bad":"How long she had been waiting?","good":"How long <b>had she been</b> waiting?","goodPlain":"How long had she been waiting?","rule":"Питальне слово + had + підмет + been + V-ing."},{"title":"Have been замість had been","bad":"He have been waiting when I came.","good":"He <b>had been</b> waiting when I came.","goodPlain":"He had been waiting when I came.","rule":"У минулому — had been; have been — для теперішнього."}]}$g134$::jsonb, null, 18, $g135$past_perf_cont$g135$
