insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position, subtopic)
select id, $g137$pmix_choose$g137$, $g138$Як вибрати минулий час$g138$, $g139$elementary$g139$, $g140$cases$g140$, $g141${"kicker":"Порівняння чотирьох часів","lead":"Поставте собі три запитання: <b>дія завершена чи в процесі?</b> <b>раніше за іншу минулу дію?</b> <b>результат чи тривалість?</b> Відповіді підкажуть час.","cards":[{"icon":"1","title":"Past Simple","text":"Завершена дія, послідовність дій, минулі звички. Слова: yesterday, ago, last week, in 2019.","example":"She <b>came</b> at five. He <b>opened</b> the door and <b>went</b> in.","examplePlain":"She came at five. He opened the door and went in."},{"icon":"2","title":"Past Continuous","text":"Дія в процесі в певний момент, фон для іншої дії, одночасні дії. Слова: while, at 5 o'clock yesterday, all day.","example":"I <b>was reading</b> when the phone <b>rang</b>.","examplePlain":"I was reading when the phone rang."},{"icon":"3","title":"Past Perfect","text":"Дія раніше за іншу минулу дію або до моменту. Слова: by, by the time, before, after, already.","example":"When I <b>came</b>, they <b>had</b> already <b>left</b>.","examplePlain":"When I came, they had already left."},{"icon":"4","title":"Past Perfect Continuous","text":"Дія тривала певний час до моменту чи іншої минулої дії, або причина стану. Слова: for, since, all day, how long.","example":"He was tired because he <b>had been working</b> all day.","examplePlain":"He was tired because he had been working all day."}],"axis":{"title":"Те саме в чотирьох часах","points":[{"label":"Simple","text":"He read a book (факт)"},{"label":"Continuous","text":"He was reading a book (процес)"},{"label":"Perfect","text":"He had read the book (раніше, завершено)"},{"label":"Perfect Cont.","text":"He had been reading for an hour (тривало до моменту)"}]}}$g141$::jsonb, null, 19, $g142$past_mix$g142$
