  ($g764$pst_ex18_4$g764$, $g765$gap$g765$, $g766$intermediate$g766$, $g767${"id":"pst_ex18_4","level":"intermediate","group":18,"gord":18,"no":4,"groupTitle":"Past Perfect","instruction":"Put the verbs in brackets into the correct form.","prompt":"How many patients ______ the doctor ______ (to examine) by the end of the day?","answers":["had · examined"],"blanks":[["had"],["examined"]],"explanation":"By the end of the day (до певного моменту) → Past Perfect."}$g767$, 39, $g768$past_perf$g768$),
